u32 kvm_lapic_get_current_timer_count(struct kvm_lapic *apic)
{
    u64 period;
    s64 remaining;

    if (!apic || apic->base.read.lapic_timer_initial_count == 0 ||
        apic->base.read.lapic_timer_period == 0)
        return 0;

    remaining = apic->base.read.lapic_timer_initial_count;
    period = apic->base.read.lapic_timer_period;

    remaining = (remaining * 1000000000ULL) / period;

    if (remaining < 0)
        remaining = 0;

    return (u32)((remaining % period) / (apic->base.read.lapic_timer_divide_count));
}

u32 kvm_apic_get_current_timer_count(struct kvm_lapic *apic) {
    u64 period;
    u64 remaining;
    u64 bus_clock;
    u32 count;

    if (!apic)
        return 0;

    if (apic->base.read(APIC_TMICT) == 0 || apic->base.read(APIC_TDCR) == 0)
        return 0;

    period = apic->base.read(APIC_TMICT);
    bus_clock = APIC_BUS_CYCLE_NS / (1 << apic->base.read(APIC_TDCR));
    remaining = period - apic->base.read(APIC_TMR);

    if (remaining < 0)
        remaining = 0;

    count = (u32)(remaining / bus_clock);

    return count;
}

u32 kvm_lapic_get_current_timer_count(struct kvm_lapic *apic)
{
    u64 remaining;
    u32 count;

    if (!apic || apic->base.initial_count == 0 || apic->base.timer_period == 0)
        return 0;

    remaining = apic->base.initial_count;
    remaining = apic->base.initial_count - (kvm_get_wall_time_us() - apic->base.last_update_time);
    if (remaining < 0)
        remaining = 0;

    count = (u32)((remaining % apic->base.timer_period) /
                   apic->base.divide_count);

    return count;
}

u32 kvm_apic_get_current_timer_count(struct kvm_lapic *apic) {
    u64 remaining, period;

    if (!apic)
        return 0;

    if (apic->base.lvt_timer.initial_count == 0 || apic->base.lvt_timer.timer_period == 0)
        return 0;

    remaining = apic->base.lvt_timer.initial_count -
                apic->base.lvt_timer.current_count;
    period = apic->base.lvt_timer.timer_period;

    if (remaining < 0)
        remaining = 0;

    return (u32)((remaining % period) / (apic->base.divide_count + 1));
}

u32 kvm_lapic_get_current_timer_count(struct kvm_lapic *apic) {
    if (!apic || !apic->timer_period || !apic->regs[KVM_APIC_INIT_COUNT / 4])
        return 0;

    s64 remaining = apic->regs[KVM_APIC_INIT_COUNT / 4];
    remaining -= ktime_get_ns() - apic->last_update;
    if (remaining < 0)
        remaining = 0;

    return (u32)((remaining % apic->timer_period) / apic->bus_cycle_duration);
}
